#!/usr/bin/env bash
# Fully generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
#
# Self-test for tests/check_retest_window.sh. A synthetic census §4.5 and a
# stub `gh` on PATH keep it offline and deterministic: the stub answers the two
# endpoints the gate uses, so the parsed pairs, the pre/post-expiry split, and
# the silent-vs-replied distinction are all pinned without a network.
#
# Exit codes: 0 all cases pass, 1 a case mismatched, 2 setup failed.
set -u

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
GATE="$ROOT/tests/check_retest_window.sh"
[ -f "$GATE" ] || { echo "self-test: gate not found at $GATE" >&2; exit 2; }

if command -v cygpath >/dev/null 2>&1 && [ -n "${USERPROFILE:-}" ]; then
    tmpbase=$(cygpath -w "$USERPROFILE/AppData/Local/Temp")
else
    tmpbase="${TMPDIR:-/tmp}"
fi
SANDBOX="$(mktemp -d "$tmpbase/pime-retest-window-selftest.XXXXXX")" || {
    echo "self-test: no sandbox" >&2; exit 2; }
trap 'rm -rf "$SANDBOX"' EXIT

failures=0
check() { # name want got
    if [ "$2" = "$3" ]; then
        printf 'ok    %s (rc %s)\n' "$1" "$3"
    else
        printf 'FAIL  %s: want rc %s, got rc %s\n' "$1" "$2" "$3"
        failures=$((failures + 1))
    fi
}

# The stub: two endpoints, each answered from a file the case writes.
cat >"$SANDBOX/gh" <<'STUB'
#!/usr/bin/env bash
for a in "$@"; do
    case "$a" in
        *issues?state=all*) [ -f "${STUB_STATES:-}" ] && cat "$STUB_STATES" ; exit 0 ;;
        *comments*)        [ -f "${STUB_LAST:-}" ] && cat "$STUB_LAST" ; exit 0 ;;
    esac
done
exit 0
STUB

# A census with a §4.5 block: heading count, expiry line, and a five-pair row.
make_census() { # file expiry-count claim
    {
        printf '### 4.5 Stale unreproducible (%s)\n' "$2"
        printf 'The house pattern: bilingual retest request, close if silent.\n'
        printf '**14 days, expiring %s — a silent issue is closed.**\n' "$3"
        printf '\n| # | comment id | # | comment id | # | comment id |\n'
        printf '|---|---|---|---|---|\n'
        printf '| 12 | 6826100120 | 18 | 6826100588 | 36 | 6826101079 |\n'
        printf '\n### 4.6 Unclear (22)\n'
    } >"$1"
}

run_gate() { # census-file
    ( cd "$ROOT" && PATH="$SANDBOX:$PATH" STUB_STATES="$SANDBOX/states" STUB_LAST="$SANDBOX/last" \
        bash "$GATE" "$1" ) >/dev/null 2>&1
    printf '%s' "$?"
}

census="$SANDBOX/census.md"

# 1. Window still open and every issue already closed.
make_census "$census" 3 2099-01-01
printf '12 closed\n18 closed\n36 closed\n' >"$SANDBOX/states"
check "window open, all closed" 0 "$(run_gate "$census")"

# 2. Window still open with an issue still open: the expected state.
printf '12 open\n18 closed\n36 open\n' >"$SANDBOX/states"
check "window open, issues still open" 0 "$(run_gate "$census")"

# 3. Window shut, a silent issue left open — the miss the gate exists for.
make_census "$census" 3 2000-01-01
printf '12 open\n18 closed\n36 closed\n' >"$SANDBOX/states"
printf '6826100120\n' >"$SANDBOX/last"
check "window shut, silent issue open" 1 "$(run_gate "$census")"

# 4. Window shut, the open issue answered after the request.
printf '9999999999\n' >"$SANDBOX/last"
check "window shut, reporter replied" 0 "$(run_gate "$census")"

# 5. The heading count no longer matches the table rows.
make_census "$census" 9 2000-01-01
check "heading count disagrees with the rows" 1 "$(run_gate "$census")"

# 6. No expiry date in the section.
{
    printf '### 4.5 Stale unreproducible (3)\n'
    printf '| # | comment id |\n|---|---|\n| 12 | 1 |\n'
} >"$census"
check "no expiry stated" 1 "$(run_gate "$census")"

# 7. No §4.5 at all: nothing to grade.
printf '# Census\n\n### 4.6 Unclear (22)\n' >"$census"
check "no §4.5 section" 125 "$(run_gate "$census")"

# 8. No `gh` on this box: not applicable.
( cd "$ROOT" && GH_BIN=pime-no-such-gh bash "$GATE" "$census" ) >/dev/null 2>&1
check "no gh on PATH" 125 "$?"

if [ "$failures" -ne 0 ]; then
    printf 'Self-test failed (%d case(s))\n' "$failures" >&2
    exit 1
fi
echo "Self-test passed"
